module clkgenerator #(
    parameter PERIOD = 10
) (
    output reg clk
);
    initial $display("PERIOD: %d", PERIOD);
    reg clk_reg = 0;
    assign clk = clk_reg;
    integer counter = 0;
    always @(posedge clk_reg) begin
        counter = counter + 1;
        if(counter >= PERIOD / 2) begin
            clk_reg <= !clk_reg;
            counter = 0;
        end
    end
endmodule
